mapper.insert:
insert into orders(number, user_id, address_book_id, order_time, checkout_time, amount,
                   remark, phone, address, user_name, consignee, cancel_reason, rejection_reason,
                   cancel_time, estimated_delivery_time, delivery_time, pack_amount, tableware_number)
values(#{number},#{userId},#{addressBookId},#{orderTime},#{checkoutTime},#{amount},#{remark},#{phone}
      ,#{address},#{userName},#{consignee},#{cancelReason},#{rejectionReason},#{cancelTime},#{estimatedDeliveryTime}
      ,#{deliveryTime},#{packAmount},#{tablewareNumber})

mapper.select:
select * from orders 

    and user_id=#{userId}


    and number like concat("%",#{number},"%")


    and status=#{status}


    and phone like concat('%',#{phone},'%')


    and order_time>=#{beginTime}


    and order_time <=#{endTime}


order by order_time desc
